#include <bits/stdc++.h>
using namespace std;

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int x;
	cin >> x;
	priority_queue<int> L;
	priority_queue<int, vector<int>, greater<int>> R;
	L.push(x);
	auto add = [&](int val) {
		if (val <= L.top()) {
			L.push(val);
		} else {
			R.push(val);
		}
		if (L.size() < R.size() + 1) {
			L.push(R.top());
			R.pop();
		}
		if (L.size() > R.size() + 1) {
			R.push(L.top());
			L.pop();
		}
	};
	int Q;
	cin >> Q;
	while (Q--) {
		int a, b;
		cin >> a >> b;
		add(a), add(b);
		cout << L.top() << '\n';
	}
	return 0;
}

import sys

input = sys.stdin.readline
from heapq import heappush, heappop

L = [-int(input())]
R = []


def add(x):
    if x <= -L[0]:
        heappush(L, -x)
    else:
        heappush(R, x)

    if len(L) < len(R) + 1:
        heappush(L, -heappop(R))
    if len(L) > len(R) + 1:
        heappush(R, -heappop(L))


for _ in range(int(input())):
    a, b = map(int, input().split())
    add(a), add(b)
    print(-L[0])
